"""Trusted pytest wrapper around explicitly reviewed Ollama-created case data. No generated code is executed."""
import json
import pytest
from healthcare_quality.ai_schema import contract_fingerprint, digest, validate_cases
from healthcare_quality.ai_runner import run_cases
SNAPSHOT = json.loads('{"approval": {"at": "2026-11-12T03:48:50.205255+00:00", "expectations_checked": true, "hashes": {"AI-001": "e0c26e9c7e20d2d33fa56f1a4ba622ac8a4958c35fd24582bb9b275265ba6777", "AI-002": "eaaee0b9bcd1e2613c8977d63cf80d8b28312eeae5116c661ffaf9dfef5d1284"}, "identity_mode": "Local attestation label, not authenticated human identity", "note": "Rechecked added monetary and event assertions: 100000-10000=90000 cents; successful revisions/events 1,2,3; payment exists only after paid. Engineering attestation, not user sign-off.", "reviewer_label": "Codex engineering demo \\u2014 not learner approval", "revision": 5}, "cases": [{"assumptions": [], "id": "AI-001", "rationale": "Test duplicate claim submission and handling.", "rule_ids": ["WF-002", "HC-007", "WF-005"], "steps": [{"action": "submit", "actor": "customer-m100", "data": {"amount_cents": 100000, "claim_id": "C10001", "member_id": "M100", "service": "medical"}, "expect": {"claim_status": "submitted", "event_count": 1, "payment_cents": null, "payout_cents": 90000, "revision": 1, "status": 201}}, {"action": "submit", "actor": "customer-m100", "data": {"amount_cents": 100000, "claim_id": "C10001", "member_id": "M100", "service": "medical"}, "expect": {"error": "DUPLICATE_CLAIM", "status": 409}}, {"action": "read", "actor": "customer-m100", "data": {"claim_id": "C10001"}, "expect": {"claim_status": "submitted", "event_count": 1, "payment_cents": null, "payout_cents": 90000, "revision": 1, "status": 200}}], "title": "Duplicate Claim Submission Test"}, {"assumptions": [], "id": "AI-002", "rationale": "Test claim lifecycle from submission to paid.", "rule_ids": ["WF-002", "WF-003", "WF-004", "HC-007", "WF-005"], "steps": [{"action": "submit", "actor": "customer-m100", "data": {"amount_cents": 100000, "claim_id": "C10002", "member_id": "M100", "service": "medical"}, "expect": {"claim_status": "submitted", "event_count": 1, "payment_cents": null, "payout_cents": 90000, "revision": 1, "status": 201}}, {"action": "transition", "actor": "adjuster-demo", "data": {"claim_id": "C10002", "target": "approved"}, "expect": {"claim_status": "approved", "event_count": 2, "payment_cents": null, "payout_cents": 90000, "revision": 2, "status": 200}}, {"action": "transition", "actor": "finance-demo", "data": {"claim_id": "C10002", "target": "paid"}, "expect": {"claim_status": "paid", "event_count": 3, "payment_cents": 90000, "payout_cents": 90000, "revision": 3, "status": 200}}, {"action": "read", "actor": "customer-m100", "data": {"claim_id": "C10002"}, "expect": {"claim_status": "paid", "event_count": 3, "payment_cents": 90000, "payout_cents": 90000, "revision": 3, "status": 200}}], "title": "Claim Lifecycle Test"}], "contract_fingerprint": "3b062e81b83724527d2afc4c8cb85cd07849d074f682023038eaed89825c43dc", "experiment_id": "12758a0998ed475dbdae3d79fd7ff506", "source_ids": ["WF-002", "WF-003", "WF-004", "WF-005", "HC-007"]}')
pytestmark = [pytest.mark.ai, pytest.mark.regression]
@pytest.mark.parametrize("case", SNAPSHOT["cases"], ids=lambda case: case["id"])
def test_reviewed_ollama_case(case):
    assert SNAPSHOT["contract_fingerprint"] == contract_fingerprint(), "Stale contract/schema; review again"
    assert digest(case) == SNAPSHOT["approval"]["hashes"][case["id"]], "Snapshot changed"
    assert validate_cases([case], SNAPSHOT["source_ids"])[0]["valid"]
    result = run_cases([case])
    assert result["failed"] == 0, json.dumps(result, indent=2)
